    async def renew(
        self,
        domain_name: str,
        body: RenewDomainDto,
        *,
        options: RequestOptions | None = None,
    ) -> DomainRenewalResponseDto:
        """Renew a domain

        Extends the domain by `period` years and charges your balance. Add-ons attached to the domain (for
        example local presence) are renewed for the same years and included in the charge; they cannot be
        left out. If validation or the registry rejects the request, nothing is charged.

        - Domains in the grace period (`expired`) can be renewed and become `active` again. Deleted domains
          need `POST /domain/{domainName}/restore`.
        - The domain must not be update-locked. `period` must be within the TLD renewal rules.
        - `expectedPrice` (optional): the `total` from `GET /domain/quote` for the renewal, add-ons
          included. If the current total differs by more than 0.01, the request fails with 409
          `PRICE_CHANGED` and `expected`, `actual` and `currency` next to `code`, and nothing is charged.
        - `Idempotency-Key` header (optional, recommended): a retry with the same key within 24 hours
          returns the first successful response without charging again.
        - For the .kr family a renewal can be cancelled for a refund within 7 days with `DELETE
          /domain/{domainName}/renewal/{transactionId}`, using `data.renewalId`.

        Charges the balance. An Idempotency-Key is sent with every call (generated unless you pass one in
        `options`), so the SDK can retry it safely and a repeat with the same key is not charged twice.

        Body fields:
        - `period` (required): Renewal period in years. The TLD may set a narrower range (`rules.renewal` in
          the pricing); outside it the request fails with `DOMAIN_INVALID_PERIOD`.
        - `expectedPrice`: Total you expect to be charged for this renewal (including add-ons attached to
          the domain), in the account currency (the `total` of `GET /domain/quote`). If the actual total
          differs by more than 0.01 (for example because a promotion ended), the request fails with 409 and
          `code: PRICE_CHANGED` together with `expected`, `actual` and `currency`, and nothing is charged.
          Omit to charge the current price without checking.

        Errors (LetoApiError, branch on error_code):
        - 400: `DOMAIN_INVALID_PERIOD`: `period` is outside the TLD renewal rules. `DOMAIN_UPDATE_LOCKED`:
          the domain has an update lock. `DOMAIN_INVALID_STATUS`: the domain is `deleted`. `BAD_REQUEST`: no
          price for the TLD, an invalid `expectedPrice`, or the registry rejected the renewal.
          `IDEMPOTENCY_KEY_INVALID`: malformed Idempotency-Key.
        - 402: `BALANCE_INSUFFICIENT`: not enough balance. Nothing was charged.
        - 404: `DOMAIN_NOT_FOUND`: the domain is not in your account. `DOMAIN_NOT_REGISTERED`: the domain
          has no registry record.
        - 409: `PRICE_CHANGED`: `expectedPrice` differs from the current total; the body adds `expected`,
          `actual` and `currency`. `IDEMPOTENCY_REQUEST_IN_PROGRESS`: a request with the same
          Idempotency-Key is still running (see `Retry-After`).
        - 422: `IDEMPOTENCY_KEY_REUSED`: the Idempotency-Key was used for a different request.
        - 502: `REGISTRY_CONNECTION_FAILED`: the registry could not be reached. Nothing was charged.

        HTTP: `POST /api/v1/domain/{domainName}/renewal`

        Args:
            domain_name: A domain in your account, in ASCII form (use punycode `xn--` for internationalized
                names).
            body: Request body (fields listed above).
            options: Idempotency-Key, retries and extra headers for this call. A key is generated when you
                do not pass one.

        Returns:
            DomainRenewalResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "POST",
            "/api/v1/domain/{domainName}/renewal",
            path_params={"domainName": domain_name},
            body=body,
            options=options,
            idempotent=True,
        )
        return cast(DomainRenewalResponseDto, response)

    async def restore(self, domain_name: str, *, options: RequestOptions | None = None) -> DomainRestoreResponseDto:
        """Restore a deleted domain

        Brings back a domain that was deleted because it was not renewed before the grace period ended
        (registry redemption). Domains still in the grace period (`expired`) are renewed instead, and
        domains you deleted yourself cannot be restored. The registry must support restore (otherwise 409).
        Your balance is charged the 1-year renewal price plus the registry restore fee; if the registry
        refuses, nothing is charged. DNS zones and forwarding rules removed at deletion are not restored.
        `Idempotency-Key` header (optional, recommended): a retry with the same key within 24 hours returns
        the first successful response without charging again. Console members need the ADMIN role; API keys
        are not restricted.

        Charges the balance. An Idempotency-Key is sent with every call (generated unless you pass one in
        `options`), so the SDK can retry it safely and a repeat with the same key is not charged twice.

        Errors (LetoApiError, branch on error_code):
        - 400: `DOMAIN_INVALID_STATUS`: the domain is not `deleted`. `IDEMPOTENCY_KEY_INVALID`: malformed
          Idempotency-Key.
        - 402: `BALANCE_INSUFFICIENT`: not enough balance. Nothing was charged.
        - 403: `FORBIDDEN`: a console (SSO) member below ADMIN. API keys are not restricted.
        - 404: `DOMAIN_NOT_FOUND`: the domain is not in your account.
        - 409: `OPERATION_NOT_ALLOWED`: the domain was not deleted after expiry, it has been registered
          again, the registry does not support restore, or no restore fee is published for the TLD.
          `IDEMPOTENCY_REQUEST_IN_PROGRESS`: a request with the same Idempotency-Key is still running.
        - 422: `IDEMPOTENCY_KEY_REUSED`: the Idempotency-Key was used for a different request.
        - 502: `OPERATION_NOT_ALLOWED`: the registry refused the restore. Nothing was charged.

        HTTP: `POST /api/v1/domain/{domainName}/restore`

        Args:
            domain_name: A domain in your account, in ASCII form (use punycode `xn--` for internationalized
                names).
            options: Idempotency-Key, retries and extra headers for this call. A key is generated when you
                do not pass one.

        Returns:
            DomainRestoreResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "POST",
            "/api/v1/domain/{domainName}/restore",
            path_params={"domainName": domain_name},
            options=options,
            idempotent=True,
        )
        return cast(DomainRestoreResponseDto, response)

